<script setup lang="ts">import{ref}from'vue';import AccountShell from'../components/AccountShell.vue';import{useAppStore}from'../stores/app';const open=ref(false),store=useAppStore();const addresses=ref([{name:'Alex Rivers',phone:'+1 415 ••• 8899',region:'美国 / UNITED STATES',line:'12 Market Street, San Francisco, CA 94105',def:true},{name:'Alex Rivers',phone:'+81 90 •••• 2233',region:'日本 / JAPAN',line:'東京都渋谷区神宮前 1-2-3, 150-0001',def:false}]);function save(){open.value=false;store.toast('地址已保存')}</script>
<template><AccountShell><div class="title"><div><span class="eyebrow">ADDRESS BOOK</span><h1>地址簿</h1><p>管理卡牌发货使用的收货信息。</p></div><button class="btn btn-primary" @click="open=true">＋ 添加新地址</button></div><div class="address-list"><article v-for="(a,i) in addresses" class="address-card card"><div class="location">⌖</div><div><span class="eyebrow">{{a.region}}</span><h2>{{a.name}} <span v-if="a.def" class="pill gold">默认地址</span></h2><p>{{a.phone}}</p><p>{{a.line}}</p><small>已提交的发货订单会保留提交时的地址快照。</small></div><div class="address-actions"><button class="btn btn-outline" @click="open=true">编辑</button><button v-if="!a.def" class="btn btn-outline" @click="addresses.forEach(x=>x.def=false);a.def=true;store.toast('已设为默认地址')">设为默认</button><button class="btn btn-danger" :disabled="a.def">删除</button></div></article></div><div class="region-tip card"><b>支持配送地区</b><span>日本 · 中国大陆 · 香港 · 澳门 · 美国</span><p>所选卡牌合计达到 2,000 Coin 后可申请标准包邮。</p></div><div v-if="open" class="drawer-mask" @click.self="open=false"><aside class="drawer"><div class="drawer-head"><div><span class="eyebrow">SHIPPING ADDRESS</span><h2>新增收货地址</h2></div><button @click="open=false">×</button></div><form @submit.prevent="save"><div class="field"><label>国家或地区</label><select><option>美国</option><option>日本</option><option>中国大陆</option><option>香港</option><option>澳门</option></select></div><div class="two"><div class="field"><label>收件人姓名</label><input required value="Alex Rivers"></div><div class="field"><label>国际区号与电话</label><input required value="+1 415 555 8899"></div></div><div class="field"><label>地址</label><input required placeholder="街道、门牌号"></div><div class="two"><div class="field"><label>城市</label><input required value="San Francisco"></div><div class="field"><label>州 / 省</label><input required value="California"></div></div><div class="field"><label>邮编</label><input required value="94105"></div><label class="check"><input type="checkbox"> 设为默认地址</label><div class="drawer-actions"><button type="button" class="btn btn-outline" @click="open=false">取消</button><button class="btn btn-primary">保存地址</button></div></form></aside></div></AccountShell></template>
